import{_ as r,l as i,o as e,c as s,v as t,p as n,x as o,d as p,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const H=JSON.parse('{"title":"输出排队与 HOL","description":"","frontmatter":{"title":"输出排队与 HOL","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/output-queue-hol.md","filePath":"cs/output-queue-hol.md","lastUpdated":1789023840000}'),c={name:"cs/output-queue-hol.md"};function u(O,a,E,_,m,A){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="输出排队与-hol" tabindex="-1">输出排队与 HOL <a class="header-anchor" href="#输出排队与-hol" aria-label="Permalink to &quot;输出排队与 HOL&quot;">​</a></h1><div class="epigraph"><p>入口 FIFO 里队头帧要去的出口忙，后面去往空闲口的帧也被挡住；虚拟输出排队把目的拆开，结构再调度。</p><footer>—— 据 Karol, Hluchyj and Morgan, 1987；McKeown, iSLIP, IEEE/ACM ToN 1999 整理</footer></div><p><a href="/cs/switch-fabric">上一课</a>给出交叉开关。缺口是<strong>队头阻塞（HOL）</strong>：单 FIFO 输入排队吞吐理论上限约 58.6%（独立均匀目的）。输出排队理想但要结构 \\(N\\) 倍加速。工程折中：VOQ + 匹配调度。本课结束「信号到以太网」课序；下一课序换无线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>输出排队：帧一进结构就进目的口队列，公平、无 HOL，但 \\(N\\) 口同时向同一口发送需要内部 \\(N\\) 倍带宽。输入排队省结构，HOL 严重。VOQ：每个入口为每个出口维护队列，调度器做最大匹配或启发式（iSLIP）。PFC 暂停的是某入口某优先级，可能加重 HOL 若队列未按目的拆开。</p><p>这与 HTTP 后课的队头阻塞同名不同层：这里是交换结构，那里是 TCP 字节流。</p><p><span class="marginnote">Karol 等人给出 HOL 吞吐极限。iSLIP 是可实现的迭代匹配。本课不证极限的全部概率推导。</span></p><h3 id="结构-hol-不是-http-hol" tabindex="-1">结构 HOL 不是 HTTP HOL <a class="header-anchor" href="#结构-hol-不是-http-hol" aria-label="Permalink to &quot;结构 HOL 不是 HTTP HOL&quot;">​</a></h3><p>入 FIFO 队头挡住去往空闲口的帧。VOQ 拆目的再匹配。输出排队理想但要内部加速。PFC 冻结入口会波及无关 VOQ。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画三种排队位置。强调：MAC 学习只选出口，不消除多流争同一出口。LACP 哈希可把流打到不同成员，减轻单口热点，不消除结构 HOL。</p>',11)),(e(),n(d,null,{default:o(()=>[h(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IQ%5B%22%E5%8D%95%20FIFO%20%E5%85%A5%E9%98%9F%22%5D%20--%3E%20HOL%5B%22%E9%98%9F%E5%A4%B4%E9%98%BB%E5%A1%9E%22%5D%0A%20%20VOQ%5B%22%E6%8C%89%E7%9B%AE%E7%9A%84%20VOQ%22%5D%20--%3E%20SCH%5B%22%E5%8C%B9%E9%85%8D%E8%B0%83%E5%BA%A6%22%5D%0A%20%20OQ%5B%22%E8%BE%93%E5%87%BA%E6%8E%92%E9%98%9F%22%5D%20--%3E%20ACC%5B%22%E8%A6%81%E5%86%85%E9%83%A8%E5%8A%A0%E9%80%9F%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>线速承诺依赖调度器在时隙内完成匹配。小包使调度更频繁。巨帧占时长时隙。数据中心 incast 后课是多发送方打同一出口的应用层版本，根子仍是本课的输出热点。</p><p>PAUSE 整口停发，等于冻结该入口所有 VOQ，波及无关出口——PFC 按类缓解，不能从数学上取消 HOL。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 CIOQ 的精确加速比证明。无线与 OFDM 是下一课序第一课。后课默认：HOL 是输入 FIFO 的结构问题；VOQ 是标准对策。</p><p>不要把交换 HOL 用 TCP 窗口「解决」：窗口在端，结构在跳内。</p><p>上一课留下的缺口在本课收口；「输出排队与 HOL」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/wifi-frames-ofdm">802.11 帧与 OFDM</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>纯输入 FIFO 有 HOL 吞吐上限。</li><li>VOQ + 调度逼近输出排队，免 \\(N\\) 倍加速。</li><li>链路暂停可能冻结无关 VOQ。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Karol et al., 1987；McKeown, 1999。</li></ul>',10))])}const P=r(c,[["render",u]]);export{H as __pageData,P as default};
